<?php declare(strict_types=1); namespace Tests\Unit\Review; use App\Application\Review\Service\BuildNotebookPerformanceSummaryService;use App\Domain\Study\ReadModel\CompletedNotebookAnswer;use App\Domain\Study\Repository\NotebookProgressReaderInterface;use PHPUnit\Framework\TestCase;final class BuildNotebookPerformanceSummaryServiceTest extends TestCase {public function testBuildsMinimalPerformancePayloadFromCompletedQuestions():void{$reader=$this->createMock(NotebookProgressReaderInterface::class);$reader->expects(self::once())->method('completedAnswersForNotebook')->with('user','notebook')->willReturn([new CompletedNotebookAnswer('question-1',true,12),new CompletedNotebookAnswer('question-2',false,30)]);$summary=(new BuildNotebookPerformanceSummaryService($reader))->execute('user','notebook');self::assertSame(2,$summary->totalAnswers);self::assertSame(1,$summary->correctAnswers);self::assertSame(['notebook_id'=>'notebook','total_answers'=>2,'correct_answers'=>1,'answers'=>[['question_id'=>'question-1','is_correct'=>true,'elapsed_seconds'=>12],['question_id'=>'question-2','is_correct'=>false,'elapsed_seconds'=>30]]],$summary->toProviderPayload());}}
